globalCss:
/* Art Nouveau 全局样式 */

:root {
  --an-green: #2d5016;
  --an-gold: #c9a227;
  --an-ivory: #f5f0e1;
  --an-wisteria: #8b6db5;
}

/* 有机曲线装饰 */
.an-vine-border {
  border-image: linear-gradient(
    135deg,
    var(--an-gold) 0%,
    var(--an-green) 50%,
    var(--an-gold) 100%
  ) 1;
}

/* 金色发光效果 */
.an-gold-glow {
  box-shadow: 0 0 20px rgba(201, 162, 39, 0.3);
  transition: box-shadow 0.7s ease-in-out;
}

.an-gold-glow:hover {
  box-shadow: 0 0 35px rgba(201, 162, 39, 0.5);
}

/* 花卉背景纹理 */
.an-floral-bg {
  background-image: radial-gradient(
    circle at 20% 80%,
    rgba(139, 109, 181, 0.1) 0%,
    transparent 50%
  ),
  radial-gradient(
    circle at 80% 20%,
    rgba(201, 162, 39, 0.1) 0%,
    transparent 50%
  );
}

/* 装饰元素绽放动画 */
.an-bloom {
  transition: transform 0.7s ease-in-out, opacity 0.7s ease-in-out;
}

.an-bloom:hover {
  transform: scale(1.1) rotate(5deg);
}

/* 衬线标题 */
.an-heading {
  font-family: Georgia, "Times New Roman", serif;
  letter-spacing: 0.05em;
}
@keyframes art-nouveau-fade-in {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes art-nouveau-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.7; }
}

.art-nouveau-card {
  position: relative;
  overflow: hidden;
}

.art-nouveau-card::before {
  content: "";
  position: absolute;
  inset: 0;
  opacity: 0;
  transition: opacity 0.3s ease;
  background: linear-gradient(135deg, rgba(45, 80, 22, 0.05), transparent);
  pointer-events: none;
}

.art-nouveau-card:hover::before {
  opacity: 1;
}

.art-nouveau-frosted {
  backdrop-filter: blur(12px) saturate(180%);
  -webkit-backdrop-filter: blur(12px) saturate(180%);
  background: rgba(45, 80, 22, 0.08);
}

.art-nouveau-accent-corner {
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 2rem), calc(100% - 2rem) 100%, 0 100%);
}

.art-nouveau-animate-in {
  animation: art-nouveau-fade-in 0.5s ease-out both;
}
